// Palindrome Linked List verification
let list = AnimatedLinkedList<Int>()
list.append(1)
list.append(2)
list.append(3)
list.append(2)
list.append(1)

func isPalindrome(_ l: AnimatedLinkedList<Int>) -> Bool {
    var vals: [Int] = []
    while let val = l.remove(at: 0) {
        vals.append(val)
    }
    for v in vals {
        l.append(v)
    }
    return vals == vals.reversed()
}

let result = isPalindrome(list)
